add_filter( 'embed_defaults', 'perfectpixel_oembed_max_width' );

function perfectpixel_oembed_max_width( $size ) {
	$width = (int) '{{oembed_max_width}}';
	if ( $width < 100 ) {
		return $size;
	}
	// Same proportion WordPress uses for its own default height.
	return array(
		'width'  => $width,
		'height' => min( (int) ceil( $width * 1.5 ), 1000 ),
	);
}
